SELECT c.relname AS таблица, t.tgname AS триггер, t.tgenabled AS включён
FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
WHERE NOT t.tgisinternal ORDER BY c.relname, t.tgname;

SELECT 'обычный интервал 08:00 — 16:30' AS "случай", fn_calculate_downtime('2026-03-02 08:00+00', '2026-03-02 16:30+00') AS часов;
SELECT 'нулевой интервал', fn_calculate_downtime('2026-03-02 08:00+00', '2026-03-02 08:00+00');
SELECT 'начало не задано', fn_calculate_downtime(NULL, '2026-03-02 08:00+00');
SELECT 'перевёрнутый интервал — это ошибка данных', fn_calculate_downtime('2026-03-02 16:30+00', '2026-03-02 08:00+00');

SELECT conrelid::regclass AS таблица, conname AS ограничение
FROM pg_constraint WHERE contype = 'u' AND connamespace = 'public'::regnamespace
ORDER BY conrelid::regclass::text;

SELECT conname AS ключ, confdeltype AS on_delete
FROM pg_constraint WHERE contype = 'f' AND connamespace = 'public'::regnamespace
ORDER BY conname LIMIT 12;
